// Exact preflop all-in equity for any two specific hands, from a precomputed table.
// The table covers all 47,008 heads-up matchups that are distinct up to suit relabeling and seat swap;
// each entry stores 2·wins + ties over all 1,712,304 boards (generated by scripts/gen-preflop-table.ts,
// verified in tests/preflopTable.test.ts against the engine and against published matchups).
import type { Card } from './cards';

export const BOARDS = 1712304; // C(48, 5)
const PERMS: number[][] = [];
(function perms(a: number[], k: number) {
  if (k === a.length) PERMS.push(a.slice());
  for (let i = k; i < a.length; i++) {
    [a[k], a[i]] = [a[i], a[k]];
    perms(a, k + 1);
    [a[k], a[i]] = [a[i], a[k]];
  }
})([0, 1, 2, 3], 0);

const enc = (a: number, b: number, c: number, d: number) => ((a * 52 + b) * 52 + c) * 52 + d;

/**
 * Canonical key of the matchup (h vs v): the smallest encoding over all 24 suit permutations and both seat orders.
 * `swapped` = the canonical form has v in the first seat.
 */
export function canonKey(h1: Card, h2: Card, v1: Card, v2: Card): { key: number; swapped: boolean } {
  let best = Infinity;
  let swapped = false;
  for (const p of PERMS) {
    let a = (h1 & ~3) | p[h1 & 3];
    let b = (h2 & ~3) | p[h2 & 3];
    let c = (v1 & ~3) | p[v1 & 3];
    let d = (v2 & ~3) | p[v2 & 3];
    if (a > b) [a, b] = [b, a];
    if (c > d) [c, d] = [d, c];
    const k1 = enc(a, b, c, d);
    if (k1 < best) {
      best = k1;
      swapped = false;
    }
    const k2 = enc(c, d, a, b);
    if (k2 < best) {
      best = k2;
      swapped = true;
    }
  }
  return { key: best, swapped };
}

export interface PreflopTable {
  /** equity numerator 2W+T for the hand in the FIRST seat of the canonical key */
  get(key: number): number | undefined;
  size: number;
}

/** Build from the shipped data: delta-coded sorted keys + values. */
export function loadTable(data: { k: number[]; v: number[] }): PreflopTable {
  const map = new Map<number, number>();
  let key = 0;
  for (let i = 0; i < data.k.length; i++) {
    key += data.k[i];
    map.set(key, data.v[i]);
  }
  return { get: (k) => map.get(k), size: map.size };
}

/** Exact all-in equity of hero (h1,h2) vs villain (v1,v2) preflop. */
export function preflopEquity(t: PreflopTable, h1: Card, h2: Card, v1: Card, v2: Card): number {
  const { key, swapped } = canonKey(h1, h2, v1, v2);
  const x = t.get(key);
  if (x === undefined) throw new Error('matchup missing from preflop table');
  const firstSeat = x / (2 * BOARDS);
  return swapped ? 1 - firstSeat : firstSeat;
}

/** All canonical keys (for the generator script and tests). Deterministic, sorted. */
export function allCanonicalKeys(): number[] {
  const set = new Set<number>();
  for (let h1 = 0; h1 < 52; h1++)
    for (let h2 = h1 + 1; h2 < 52; h2++)
      for (let v1 = 0; v1 < 52; v1++) {
        if (v1 === h1 || v1 === h2) continue;
        for (let v2 = v1 + 1; v2 < 52; v2++) {
          if (v2 === h1 || v2 === h2) continue;
          set.add(canonKey(h1, h2, v1, v2).key);
        }
      }
  return [...set].sort((a, b) => a - b);
}

export function decodeKey(key: number): [Card, Card, Card, Card] {
  const d = key % 52;
  const c = Math.floor(key / 52) % 52;
  const b = Math.floor(key / 2704) % 52;
  const a = Math.floor(key / 140608);
  return [a, b, c, d];
}
